import { mkdirSync } from 'node:fs';

function globToRegExp(pattern) {
  let src = '';
  for (const ch of pattern) {
    if (ch === '*') {
      src += '.*';
    } else if (ch === '?') {
      src += '.';
    } else {
      src += ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    }
  }
  return new RegExp('^' + src + '$');
}

class Writer {
  constructor(index) {
    this._index = index;
    this._docs = [];
  }

  add_document(obj) {
    const doc = { stored: {}, tokens: {}, numeric: {} };
    for (const name of this._index.schema.names()) {
      const field = this._index.schema.get(name);
      if (!(name in obj)) continue;
      const value = obj[name];
      if (field.kind === 'numeric') {
        // validate throws on non-integer / out-of-range values
        doc.numeric[name] = field.validate(value);
      } else if (field.kind === 'text') {
        doc.tokens[name] = field.analyze(String(value));
      }
      if (field.stored) {
        doc.stored[name] = value;
      }
    }
    this._docs.push(doc);
  }

  commit() {
    this._index._docs.push(...this._docs);
    this._docs = [];
  }
}

class Searcher {
  constructor(index) {
    this._index = index;
  }

  _matches(doc, query) {
    switch (query.type) {
      case 'null':
        return false;
      case 'term': {
        const field = this._index.schema.get(query.field);
        if (field && field.kind === 'numeric') {
          const text = String(query.text).trim();
          if (!/^[+-]?\d+$/.test(text)) return false;
          const value = parseInt(text, 10);
          return doc.numeric[query.field] === value;
        }
        const tokens = doc.tokens[query.field] || [];
        return tokens.includes(query.text);
      }
      case 'wildcard': {
        const re = globToRegExp(query.pattern);
        const tokens = doc.tokens[query.field] || [];
        return tokens.some((t) => re.test(t));
      }
      case 'phrase': {
        const words = query.words;
        if (!words || words.length === 0) return false;
        const tokens = doc.tokens[query.field] || [];
        if (words.length > tokens.length) return false;
        outer: for (let i = 0; i + words.length <= tokens.length; i++) {
          for (let j = 0; j < words.length; j++) {
            if (tokens[i + j] !== words[j]) continue outer;
          }
          return true;
        }
        return false;
      }
      case 'and':
        return query.clauses.every((c) => this._matches(doc, c));
      case 'or':
        return query.clauses.some((c) => this._matches(doc, c));
      case 'not':
        if (query.clause && query.clause.type === 'null') return false;
        return !this._matches(doc, query.clause);
      default:
        return false;
    }
  }

  search(query, { limit } = {}) {
    const rows = [];
    for (const doc of this._index._docs) {
      if (limit !== undefined && limit !== null && rows.length >= limit) break;
      if (this._matches(doc, query)) {
        rows.push({ ...doc.stored });
      }
    }
    return rows;
  }
}

class Index {
  constructor(schema) {
    this.schema = schema;
    this._docs = [];
  }

  writer() {
    return new Writer(this);
  }

  searcher() {
    return new Searcher(this);
  }
}

export function create_in(dir, schema) {
  mkdirSync(dir, { recursive: true });
  return new Index(schema);
}

