// Whoosh StandardAnalyzer slice.
// Equivalent to: RegexTokenizer(r"\w+(\.?\w+)*") | LowercaseFilter | StopFilter(minsize=2).

// Stop-word list probed from the original program's whoosh build (31 words).
export const STOP_WORDS = [
  'an', 'and', 'are', 'as', 'at', 'be', 'by', 'can', 'for', 'from',
  'have', 'if', 'in', 'is', 'it', 'may', 'not', 'of', 'on', 'or',
  'that', 'the', 'this', 'to', 'us', 'we', 'will', 'with', 'yet',
  'you', 'your',
];

const STOP_SET = new Set(STOP_WORDS);

// Python r"\w+(\.?\w+)*" with re.UNICODE: \w = Unicode letters/numbers + '_'.
const TOKEN_RE = /[\p{L}\p{N}_]+(?:\.?[\p{L}\p{N}_]+)*/gu;

// Tokenize, lowercase, drop tokens shorter than 2 chars, drop stop words.
export function analyze(text) {
  if (text == null) return [];
  const tokens = [];
  for (const match of String(text).matchAll(TOKEN_RE)) {
    const token = match[0].toLowerCase();
    if (token.length < 2) continue;
    if (STOP_SET.has(token)) continue;
    tokens.push(token);
  }
  return tokens;
}

