// Whoosh field types slice: TEXT, NUMERIC, Schema.
import { analyze } from './analysis.mjs';

const INT32_MIN = -2147483648;
const INT32_MAX = 2147483647;

// TEXT(stored=True) -> stored text field analyzed with the standard analyzer.
export function TEXT(opts = {}) {
  return {
    kind: 'text',
    stored: Boolean(opts.stored),
    analyze,
  };
}

// NUMERIC(stored=True) -> stored int32 field with range validation.
export function NUMERIC(opts = {}) {
  return {
    kind: 'numeric',
    stored: Boolean(opts.stored),
    validate(value) {
      if (
        typeof value !== 'number' ||
        !Number.isInteger(value) ||
        value < INT32_MIN ||
        value > INT32_MAX
      ) {
        throw new Error(
          'Numeric field value ' + value + ' out of range [-2147483648, 2147483647]'
        );
      }
      return value;
    },
  };
}

// Schema: ordered field-name -> field-object mapping.
export class Schema {
  constructor(fields = {}) {
    this.fields = fields;
  }

  get(name) {
    return this.fields[name];
  }

  names() {
    return Object.keys(this.fields);
  }
}

