import { STOP_WORDS, analyze } from '/output/lib/analysis.mjs';
import { TEXT, NUMERIC, Schema } from '/output/lib/fields.mjs';

const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);
let pass = 0, fail = 0;
function check(name, cond) {
  if (cond) { pass++; console.log('PASS', name); }
  else { fail++; console.log('FAIL', name); }
}

// STOP_WORDS
check('stop list length 31', STOP_WORDS.length === 31);
check('stop list has expected words', ['an','and','the','your','yet'].every(w => STOP_WORDS.includes(w)));
check('stop list excludes no/but/was/they/their', ['no','but','was','they','their','there','into','such','he','she'].every(w => !STOP_WORDS.includes(w)));

// analyze
check("analyze('hello-world')", eq(analyze('hello-world'), ['hello', 'world']));
check("analyze('HELLO')", eq(analyze('HELLO'), ['hello']));
check("analyze('the hello')", eq(analyze('the hello'), ['hello']));
check("analyze('x')", eq(analyze('x'), []));
check("analyze('1_')", eq(analyze('1_'), ['1_']));
check("analyze('the x HELLO')", eq(analyze('the x HELLO'), ['hello']));
check("analyze('no but was')", eq(analyze('no but was'), ['no', 'but', 'was']));
check('stop words dropped', eq(analyze('an and are as at be by can for from have if in is it may not of on or that the this to us we will with yet you your'), []));
check('dots kept inside tokens', eq(analyze('hello.world'), ['hello.world']));
check('unicode letters', eq(analyze('Héllo'), ['héllo']));

// TEXT
const t = TEXT({ stored: true });
check('TEXT kind/stored', t.kind === 'text' && t.stored === true);
check('TEXT analyze', eq(t.analyze('the cat sat'), ['cat', 'sat']));
check('TEXT default stored false', TEXT().stored === false);

// NUMERIC
const n = NUMERIC({ stored: true });
check('NUMERIC kind/stored', n.kind === 'numeric' && n.stored === true);
check('NUMERIC accepts min', n.validate(-2147483648) === -2147483648);
check('NUMERIC accepts max', n.validate(2147483647) === 2147483647);
check('NUMERIC accepts 0', n.validate(0) === 0);

for (const bad of [2147483648, -2147483649, 1.5, '10', NaN, undefined]) {
  let msg = null;
  try { n.validate(bad); } catch (e) { msg = e.message; }
  check(`NUMERIC rejects ${String(bad)} with exact msg`,
    msg === `Numeric field value ${String(bad)} out of range [-2147483648, 2147483647]`);
}

// Schema
const schema = new Schema({ title: TEXT({ stored: true }), price: NUMERIC({ stored: true }), content: TEXT() });
check('Schema names order', eq(schema.names(), ['title', 'price', 'content']));
check('Schema get', schema.get('price').kind === 'numeric');
check('Schema get missing', schema.get('nope') === undefined);

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

