import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
import { create_in } from '/output/lib/index.mjs';

// --- inline stub schema (copy of analyzer behavior for testing only) ---
const STOP_WORDS = new Set(['an','and','are','as','at','be','by','can','for','from','have','if','in','is','it','may','not','of','on','or','that','the','this','to','us','we','will','with','yet','you','your']);
function analyze(text) {
  const tokens = text.toLowerCase().match(/\w+(\.?\w+)*/gu) || [];
  return tokens.filter((t) => t.length >= 2 && !STOP_WORDS.has(t));
}
const TEXT = (opts = {}) => ({ kind: 'text', stored: !!opts.stored, analyze });
const NUMERIC = (opts = {}) => ({
  kind: 'numeric',
  stored: !!opts.stored,
  validate(v) {
    if (!Number.isInteger(v) || v < -2147483648 || v > 2147483647) {
      throw new Error('Numeric field value ' + v + ' out of range [-2147483648, 2147483647]');
    }
    return v;
  },
});
class Schema {
  constructor(mapping) { this.fields = mapping; }
  get(name) { return this.fields[name]; }
  names() { return Object.keys(this.fields); }
}

const schema = new Schema({
  title: TEXT({ stored: true }),
  price: NUMERIC({ stored: true }),
  content: TEXT(),
});

const dir = mkdtempSync(join(tmpdir(), 'idx-test-'));
const ix = create_in(join(dir, 'indexdir'), schema);
const w = ix.writer();
w.add_document({ title: 'hello world', price: 10, content: 'item1' });
w.add_document({ title: 'hello world', price: 20, content: 'item2' });
// before commit: nothing visible
assert.equal(ix.searcher().search({ type: 'term', field: 'title', text: 'hello' }, { limit: 10 }).length, 0, 'docs visible before commit');
w.commit();
const s = ix.searcher();

const sum = (rows) => rows.reduce((a, r) => a + r.price, 0);

// term title:hello -> 2 rows, sum 30
let rows = s.search({ type: 'term', field: 'title', text: 'hello' }, { limit: 10 });
assert.equal(rows.length, 2); assert.equal(sum(rows), 30);

// wildcard hello* -> 2 rows
rows = s.search({ type: 'wildcard', field: 'title', pattern: 'hello*' }, { limit: 10 });
assert.equal(rows.length, 2);

// wildcard hel? -> 0 rows (anchored, case-sensitive vs lowercased tokens)
rows = s.search({ type: 'wildcard', field: 'title', pattern: 'hel?' }, { limit: 10 });
assert.equal(rows.length, 0);

// term content:item1 -> 1 row price 10
rows = s.search({ type: 'term', field: 'content', text: 'item1' }, { limit: 10 });
assert.equal(rows.length, 1); assert.equal(rows[0].price, 10);

// numeric term price:20 -> 1 row price 20
rows = s.search({ type: 'term', field: 'price', text: '20' }, { limit: 10 });
assert.equal(rows.length, 1); assert.equal(rows[0].price, 20);

// numeric term with non-numeric text -> no match
rows = s.search({ type: 'term', field: 'price', text: 'abc' }, { limit: 10 });
assert.equal(rows.length, 0);

// phrase [hello, world] -> 2 rows
rows = s.search({ type: 'phrase', field: 'title', words: ['hello', 'world'] }, { limit: 10 });
assert.equal(rows.length, 2);

// phrase [world, hello] -> 0 rows (order matters)
rows = s.search({ type: 'phrase', field: 'title', words: ['world', 'hello'] }, { limit: 10 });
assert.equal(rows.length, 0);

// not(term title:hello) -> 0 rows
rows = s.search({ type: 'not', clause: { type: 'term', field: 'title', text: 'hello' } }, { limit: 10 });
assert.equal(rows.length, 0);

// not(null) -> 0 rows ("-5" case)
rows = s.search({ type: 'not', clause: { type: 'null' } }, { limit: 10 });
assert.equal(rows.length, 0);

// null -> 0 rows
rows = s.search({ type: 'null' }, { limit: 10 });
assert.equal(rows.length, 0);

// limit 1 -> 1 row
rows = s.search({ type: 'term', field: 'title', text: 'hello' }, { limit: 1 });
assert.equal(rows.length, 1);

// rows expose title and price but NOT content
rows = s.search({ type: 'term', field: 'title', text: 'hello' }, { limit: 10 });
assert.deepEqual(rows[0], { title: 'hello world', price: 10 });
assert.ok(!('content' in rows[0]));

// and/or combinations
rows = s.search({ type: 'and', clauses: [
  { type: 'term', field: 'title', text: 'hello' },
  { type: 'term', field: 'content', text: 'item2' },
] }, { limit: 10 });
assert.equal(rows.length, 1); assert.equal(rows[0].price, 20);

rows = s.search({ type: 'or', clauses: [
  { type: 'term', field: 'content', text: 'item1' },
  { type: 'term', field: 'content', text: 'item2' },
] }, { limit: 10 });
assert.equal(rows.length, 2);

// numeric validation propagates from add_document
const w2 = ix.writer();
assert.throws(() => w2.add_document({ title: 'x y', price: 2147483648, content: 'z' }),
  /Numeric field value 2147483648 out of range \[-2147483648, 2147483647\]/);
assert.throws(() => w2.add_document({ title: 'x y', price: 3.5, content: 'z' }), /out of range/);

console.log('ALL TESTS PASSED');

