// qparser.mjs — minimal reimplementation of the whoosh QueryParser slice
// needed by the entry script. Produces plain-object query nodes consumed by
// index.mjs's searcher:
//   {type:'null'} | {type:'term', field, text} | {type:'wildcard', field, pattern}
//   | {type:'phrase', field, words:[...]} | {type:'and', clauses:[...]}
//   | {type:'or', clauses:[...]} | {type:'not', clause}
//
// Grammar (implicit juxtaposition = AND, precedence NOT > AND > OR):
//   or   := and (OR and)*
//   and  := unary ((AND| juxtaposition) unary)*
//   unary:= NOT unary | '-'chunk | chunk
//   chunk: optional `field:` prefix, double-quoted phrase, wildcard (* / ?),
//          or plain text (analyzed on TEXT fields, raw on NUMERIC fields).

// Split the query string into whitespace-separated chunks, keeping
// double-quoted runs together. A `field:` prefix or leading `-` directly
// before a quote (e.g. content:"two words") stays in the same chunk.
function lex(input) {
  const chunks = [];
  const n = input.length;
  let i = 0;
  while (i < n) {
    while (i < n && /\s/.test(input[i])) i++;
    if (i >= n) break;
    let text = '';
    let quoted = false;
    while (i < n && !/\s/.test(input[i])) {
      if (input[i] === '"') {
        quoted = true;
        i++;
        while (i < n && input[i] !== '"') {
          text += input[i];
          i++;
        }
        if (i < n) i++; // skip closing quote
      } else {
        text += input[i];
        i++;
      }
    }
    chunks.push({ text, quoted });
  }
  return chunks;
}

export class QueryParser {
  constructor(fieldname, schema) {
    this.fieldname = fieldname;
    this.schema = schema;
  }

  // Parse `text` into a query node. Empty / no-term queries yield {type:'null'}.
  parse(text) {
    const chunks = lex(String(text == null ? '' : text));
    this._chunks = chunks;
    this._pos = 0;
    const node = this._parseOr();
    return node === null ? { type: 'null' } : node;
  }

  _peek() {
    return this._pos < this._chunks.length ? this._chunks[this._pos] : null;
  }

  _next() {
    return this._pos < this._chunks.length ? this._chunks[this._pos++] : null;
  }

  _isKeyword(chunk, word) {
    return chunk !== null && !chunk.quoted && chunk.text === word;
  }

  _parseOr() {
    const clauses = [];
    let left = this._parseAnd();
    if (left !== null) clauses.push(left);
    while (this._isKeyword(this._peek(), 'OR')) {
      this._next();
      const right = this._parseAnd();
      if (right !== null) clauses.push(right);
    }
    if (clauses.length === 0) return null;
    if (clauses.length === 1) return clauses[0];
    return { type: 'or', clauses };
  }

  _parseAnd() {
    const clauses = [];
    let first = true;
    for (;;) {
      const peeked = this._peek();
      if (peeked === null || this._isKeyword(peeked, 'OR')) break;
      if (this._isKeyword(peeked, 'AND')) {
        this._next();
      } else if (!first) {
        // juxtaposition: implicit AND
      }
      const clause = this._parseUnary();
      if (clause !== null) clauses.push(clause);
      first = false;
    }
    if (clauses.length === 0) return null;
    if (clauses.length === 1) return clauses[0];
    return { type: 'and', clauses };
  }

  _parseUnary() {
    const chunk = this._peek();
    if (this._isKeyword(chunk, 'NOT')) {
      this._next();
      const clause = this._parseUnary();
      return { type: 'not', clause: clause === null ? { type: 'null' } : clause };
    }
    if (chunk !== null && !chunk.quoted && chunk.text.startsWith('-') && chunk.text.length > 1) {
      this._next();
      const clause = this._atom(chunk.text.slice(1), chunk.quoted, this.fieldname);
      return { type: 'not', clause: clause === null ? { type: 'null' } : clause };
    }
    const c = this._next();
    if (c === null) return null;
    return this._atom(c.text, c.quoted, this.fieldname);
  }

  // Build a query node for a single chunk. Returns null when the chunk
  // contributes nothing (no tokens after analysis, empty phrase, ...).
  _atom(text, quoted, fieldname) {
    // `field:rest` retargets to any schema field.
    const colon = text.indexOf(':');
    if (colon > 0) {
      const prefix = text.slice(0, colon);
      if (this.schema.get(prefix) !== undefined) {
        fieldname = prefix;
        text = text.slice(colon + 1);
        if (text === '') return null;
      }
    }

    const field = this.schema.get(fieldname);

    // Wildcard: raw chunk text, no analysis / lowercasing.
    if (!quoted && (text.includes('*') || text.includes('?'))) {
      return { type: 'wildcard', field: fieldname, pattern: text };
    }

    if (quoted) {
      const words = this._analyzeField(field, text);
      if (words.length === 0) return null;
      return { type: 'phrase', field: fieldname, words };
    }

    if (field && field.kind === 'numeric') {
      return { type: 'term', field: fieldname, text };
    }

    const tokens = this._analyzeField(field, text);
    if (tokens.length === 0) return null;
    if (tokens.length === 1) return { type: 'term', field: fieldname, text: tokens[0] };
    return {
      type: 'and',
      clauses: tokens.map((t) => ({ type: 'term', field: fieldname, text: t })),
    };
  }

  _analyzeField(field, text) {
    if (field && typeof field.analyze === 'function') return field.analyze(text);
    return text.split(/\s+/).filter(Boolean);
  }
}

