import { QueryParser } from '/output/lib/qparser.mjs';

// Stub schema per the fields.mjs contract (built inline; fields.mjs is another agent's file).
const STOP_WORDS = new Set(['an','and','are','as','at','be','by','can','for','from','have','if','in','is','it','may','not','of','on','or','that','the','this','to','us','we','will','with','yet','you','your']);
function analyze(text) {
  const tokens = String(text).toLowerCase().match(/\w+(\.?\w+)*/gu) || [];
  return tokens.filter((t) => t.length >= 2 && !STOP_WORDS.has(t));
}
const schema = {
  fields: {
    title: { kind: 'text', stored: true, analyze },
    price: { kind: 'numeric', stored: true, validate: (v) => v },
    content: { kind: 'text', stored: false, analyze },
  },
  get(name) { return this.fields[name]; },
  names() { return Object.keys(this.fields); },
};

const qp = new QueryParser('title', schema);
let pass = 0, fail = 0;
function check(label, actual, expected) {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a === e) { pass++; console.log('PASS', label, a); }
  else { fail++; console.log('FAIL', label, '\n  expected', e, '\n  actual  ', a); }
}

check("parse('hello')", qp.parse('hello'), { type: 'term', field: 'title', text: 'hello' });
check("parse('the hello')", qp.parse('the hello'), { type: 'term', field: 'title', text: 'hello' });
check("parse('hello*')", qp.parse('hello*'), { type: 'wildcard', field: 'title', pattern: 'hello*' });
check('parse(\'"hello world"\')', qp.parse('"hello world"'), { type: 'phrase', field: 'title', words: ['hello', 'world'] });
check("parse('content:item1')", qp.parse('content:item1'), { type: 'term', field: 'content', text: 'item1' });
check("parse('price:10')", qp.parse('price:10'), { type: 'term', field: 'price', text: '10' });
check("parse('')", qp.parse(''), { type: 'null' });
check("parse('the')", qp.parse('the'), { type: 'null' });
check("parse('-5')", qp.parse('-5'), { type: 'not', clause: { type: 'null' } });
check("parse('hello OR zz')", qp.parse('hello OR zz'),
  { type: 'or', clauses: [{ type: 'term', field: 'title', text: 'hello' }, { type: 'term', field: 'title', text: 'zz' }] });
check("parse('NOT hello')", qp.parse('NOT hello'),
  { type: 'not', clause: { type: 'term', field: 'title', text: 'hello' } });
// extra sanity checks
check("parse('hello-world')", qp.parse('hello-world'),
  { type: 'and', clauses: [{ type: 'term', field: 'title', text: 'hello' }, { type: 'term', field: 'title', text: 'world' }] });
check("parse('hello zz')", qp.parse('hello zz'),
  { type: 'and', clauses: [{ type: 'term', field: 'title', text: 'hello' }, { type: 'term', field: 'title', text: 'zz' }] });
check("parse('HELLO')", qp.parse('HELLO'), { type: 'term', field: 'title', text: 'hello' });
check("parse('price:10 OR content:item1')", qp.parse('price:10 OR content:item1'),
  { type: 'or', clauses: [{ type: 'term', field: 'price', text: '10' }, { type: 'term', field: 'content', text: 'item1' }] });
check("parse('-content:item1')", qp.parse('-content:item1'),
  { type: 'not', clause: { type: 'term', field: 'content', text: 'item1' } });
check("parse('\"the\"')", qp.parse('"the"'), { type: 'null' });
check("parse('hel?')", qp.parse('hel?'), { type: 'wildcard', field: 'title', pattern: 'hel?' });
check("parse('price:*')", qp.parse('price:*'), { type: 'wildcard', field: 'price', pattern: '*' });

console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

