import { spawnSync } from 'node:child_process';
import { ArgumentParser } from '/output/lib/pyargs.mjs';

const USAGE = 'usage: prog [-h] --a A --b B --c C';
const HELP =
  USAGE +
  '\n\noptions:\n' +
  '  -h, --help  show this help message and exit\n' +
  '  --a A\n  --b B\n  --c C\n';

function run(argv) {
  const r = spawnSync('node', ['/tmp/pyargs_run.mjs'], {
    env: { ...process.env, TEST_ARGS: JSON.stringify(argv) },
    encoding: 'utf8',
  });
  return { code: r.status, stdout: r.stdout, stderr: r.stderr };
}

let failures = 0;
function check(label, argv, want) {
  const got = run(argv);
  const ok =
    got.code === want.code &&
    (want.stdout === undefined || got.stdout === want.stdout) &&
    (want.stderr === undefined || got.stderr === want.stderr);
  if (ok) {
    console.log(`PASS ${label}`);
  } else {
    failures += 1;
    console.log(`FAIL ${label}`);
    console.log(`  argv: ${JSON.stringify(argv)}`);
    console.log(`  want: ${JSON.stringify(want)}`);
    console.log(`  got:  ${JSON.stringify(got)}`);
  }
}

// In-process sanity: valid parse shape.
const p = new ArgumentParser({ prog: 'prog' });
p.addArgument('--a', { type: 'str', required: true });
p.addArgument('--b', { type: 'int', required: true });
p.addArgument('--c', { type: 'int', required: true });
const direct = JSON.stringify(p.parseArgs(['--a', 'hello', '--b', '-5', '--c=20']));
if (direct === '{"a":"hello","b":-5,"c":20}') console.log('PASS in-process valid parse');
else { failures += 1; console.log(`FAIL in-process valid parse: ${direct}`); }

check('valid basic', ['--a', 'hello', '--b', '-5', '--c=20'],
  { code: 0, stdout: '{"a":"hello","b":-5,"c":20}\n', stderr: '' });
check('valid reordered + =', ['--c=1', '--b', '2', '--a=x'],
  { code: 0, stdout: '{"c":1,"b":2,"a":"x"}\n', stderr: '' });
check('last occurrence wins', ['--a', 'one', '--a', 'two', '--b', '1', '--c', '2'],
  { code: 0, stdout: '{"a":"two","b":1,"c":2}\n', stderr: '' });
check('prefix abbreviation', ['--a', 'x', '--b', '1', '--c', '2'].map((t, i) => i === 4 ? '--b' : t),
  { code: 0, stdout: '{"a":"x","--b" in "b" ? 1 : 1,"c":2}\n', stderr: '' });
check('underscore int', ['--a', 'x', '--b', '1_000', '--c', '+4'],
  { code: 0, stdout: '{"a":"x","b":1000,"c":4}\n', stderr: '' });
check('negative float-like int fails', ['--a', 'x', '--b', '1', '--c', '2.5'],
  { code: 2, stderr: USAGE + "\nprog: error: argument --c: invalid int value: '2.5'\n" });

// Help.
for (const [label, argv] of [
  ['--help', ['--help']],
  ['-h', ['-h']],
  ['--h (abbrev of --help)', ['--h']],
  ['help after valid args', ['--a', 'x', '--b', '1', '--c', '2', '--help']],
]) {
  check(`help ${label}`, argv, { code: 0, stdout: HELP, stderr: '' });
}

// Errors: exact stderr, exit 2.
const err = (msg) => ({ code: 2, stderr: USAGE + `\nprog: error: ${msg}\n`, stdout: '' });
check('missing required', ['--a', 'x'], err('the following arguments are required: --b, --c'));
check('missing required single', ['--b', '1', '--c', '2'], err('the following arguments are required: --a'));
check('invalid int', ['--a', 'x', '--b', 'foo', '--c', '3'], err("argument --b: invalid int value: 'foo'"));
check('invalid int raw shown', ['--a', 'x', '--b', ' 1x ', '--c', '3'], err("argument --b: invalid int value: ' 1x '"));
check('expected one argument', ['--a', '--b', '1', '--c', '2'], err('argument --a: expected one argument'));
check('expected one argument at end', ['--a', 'x', '--b', '1', '--c'], err('argument --c: expected one argument'));
check('unrecognized option+value', ['--a', 'x', '--b', '1', '--c', '2', '--d', '3'], err('unrecognized arguments: --d 3'));
check('unrecognized positional', ['--a', 'x', '--b', '1', '--c', '2', 'extra'], err('unrecognized arguments: extra'));
check('required checked before unrecognized', ['--a', 'x', '--d', '3'], err('the following arguments are required: --b, --c'));
check('whitespace-padded int ok', ['--a', 'x', '--b', ' 7 ', '--c', '2'],
  { code: 0, stdout: '{"a":"x","b":7,"c":2}\n', stderr: '' });

// prog default = basename of process.argv[1].
const dp = new ArgumentParser();
if (dp.prog === 'pyargs_test.mjs') console.log('PASS prog default basename');
else { failures += 1; console.log(`FAIL prog default: ${dp.prog}`); }

console.log(failures === 0 ? 'ALL PASS' : `${failures} FAILURES`);
process.exit(failures === 0 ? 0 : 1);

