import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { ArgumentParser } from './lib/pyargs.mjs';
import { Schema, TEXT, NUMERIC } from './lib/fields.mjs';
import { create_in } from './lib/index.mjs';
import { QueryParser } from './lib/qparser.mjs';

const parser = new ArgumentParser();
parser.addArgument('--a', { type: 'str', required: true });
parser.addArgument('--b', { type: 'int', required: true });
parser.addArgument('--c', { type: 'int', required: true });
const args = parser.parseArgs(process.argv.slice(2));

const schema = new Schema({ title: TEXT({ stored: true }), price: NUMERIC({ stored: true }), content: TEXT() }); // Create schema with NUMERIC field
const tempDir = mkdtempSync(join(tmpdir(), 'test15-')); // Create temp dir
const ix = create_in(tempDir, schema); // Create index
const writer = ix.writer(); // Create writer
writer.add_document({ title: args.a, price: args.b, content: 'item1' }); // Add first document
writer.add_document({ title: args.a, price: args.c, content: 'item2' }); // Add second document
writer.commit(); // Commit
const searcher = ix.searcher(); // Create searcher
const query = new QueryParser('title', ix.schema).parse(args.a); // Parse query
const results = searcher.search(query, { limit: 10 }); // Search with limit
let totalPrice = 0;
for (const r of results) totalPrice += r.price; // Sum prices from results
console.log(totalPrice); // Print total price
